import java.util.Arrays;
class Solution {
  static int duplicateNumber(int[] nums) {
    int left = 0;
    int right = nums.length;

    while (left + 1 < right) {
      int mid = (right + left) / 2;

      if (nums[mid] == nums[mid - 1]) {
        return -999;
      } else if (nums[mid] > mid) {
        left = mid;
      } else {
        right = mid;
      }
    }

    return -999;
  }
}
